// Returns false for an invalid |document|, or for NULL |data| with a
// non-zero |size|.
FPDF_EXPORT FPDF_BOOL FPDF_CALLCONV
EPDFCatalog_SetMetadata(FPDF_DOCUMENT document, const void* data, unsigned long size);

