FPDF_EXPORT int FPDF_CALLCONV EPDFFontFaces_GetWeight(EPDF_FONT_FACES faces,
                                                      int face);
FPDF_EXPORT FPDF_BOOL FPDF_CALLCONV
EPDFFontFaces_IsItalic(EPDF_FONT_FACES faces, int face);

