EPDFDoc_GetPieceInfoEntryCount(FPDF_DOCUMENT document);
FPDF_EXPORT unsigned long FPDF_CALLCONV
EPDFDoc_GetPieceInfoEntryAt(FPDF_DOCUMENT document,
                            int index,
                            char* buffer,
