FPDF_EXPORT FPDF_BOOL FPDF_CALLCONV EPDFFont_GetMetrics(EPDF_FONT_ID font_id,
                                                        float* ascent,
                                                        float* descent);

// Experimental EmbedPDF Extension API.
// A registered font's PostScript name, as its embedded /BaseFont spells it
