FPDF_EXPORT void FPDF_CALLCONV
EPDFDoc_ClearMissingCharacters(FPDF_DOCUMENT document);
FPDF_EXPORT int FPDF_CALLCONV
EPDFDoc_CountMissingCharacters(FPDF_DOCUMENT document);
