EPDFForm_SetFieldFlags(FPDF_DOCUMENT document,
                       uint32_t field_objnum,
                       uint32_t set_bits,
                       uint32_t clear_bits);

// Experimental EmbedPDF Extension API.
// Set a field's action for |event| (EPDF_FORM_ACTION_*: /AA K F V C) to a
