EPDFDoc_GetPieceInfoLastModified(FPDF_DOCUMENT document,
                                 FPDF_BYTESTRING application,
                                 FPDF_WCHAR* buffer,
                                 unsigned long buflen);

FPDF_EXPORT int FPDF_CALLCONV
EPDFDoc_GetPieceInfoKeyCount(FPDF_DOCUMENT document,
                             FPDF_BYTESTRING application);
