// Returns the length of the relationship name in bytes.
FPDF_EXPORT unsigned long FPDF_CALLCONV
FPDFAttachment_GetAFRelationship(FPDF_ATTACHMENT attachment,
                                 FPDF_WCHAR* buffer,
                                 unsigned long buflen);

