FPDF_EXPORT int FPDF_CALLCONV
FPDFPageObj_GetMarkedContentID(FPDF_PAGEOBJECT page_object);

// Experimental API.
// Get number of content marks in |page_object|.
//
//   page_object - handle to a page object.
//
