//! Explicit PDF destinations.
//!
//! G6. A transcription of `services/src/features/destinations/*` and
//! `core/src/dto/PdfDestination.ts`.
//!
//! A page, a location and a magnification, per ISO 32000-1 12.3.2.2. Named
//! destinations resolve through the catalog before reaching here, so only the
//! explicit form exists in this type and a viewer never sees a name.
//!
//! Coordinates are PDF user space: y-up, points, absolute rather than
//! crop-relative. `None` means "retain the current value", which is the spec's
//! meaning for a null array entry. The wire hands destinations out in page
//! space ([`crate::page_space::destinations::PageDestination`]); this is the
//! file's form, which readers make and writers take.

use serde::{Deserialize, Serialize};

use pdfium::RawDestination;

use crate::identity::PageObjectNumber;

/// Where a destination puts the reader.
///
/// The optional coordinates serialize as `null` rather than being omitted.
/// `null` is the spec's "retain the current value", which is a thing the
/// document said; an absent key would be indistinguishable from a producer
/// that never wrote the entry, and the TypeScript emits the key either way.
#[derive(Debug, Clone, Copy, PartialEq, Serialize, Deserialize)]
#[serde(tag = "kind", rename_all = "camelCase")]
pub enum PdfDestination {
    /// A point and a zoom. Any of the three may retain the current value.
    Xyz {
        #[serde(rename = "page", with = "crate::identity::page_ref")]
        page_object_number: PageObjectNumber,
        left: Option<f64>,
        top: Option<f64>,
        zoom: Option<f64>,
    },
    Fit {
        #[serde(rename = "page", with = "crate::identity::page_ref")]
        page_object_number: PageObjectNumber,
    },
    #[serde(rename = "fitH")]
    FitH {
        #[serde(rename = "page", with = "crate::identity::page_ref")]
        page_object_number: PageObjectNumber,
        top: Option<f64>,
    },
    #[serde(rename = "fitV")]
    FitV {
        #[serde(rename = "page", with = "crate::identity::page_ref")]
        page_object_number: PageObjectNumber,
        left: Option<f64>,
    },
    /// A rectangle, the one kind whose coordinates are all required.
    #[serde(rename = "fitR")]
    FitR {
        #[serde(rename = "page", with = "crate::identity::page_ref")]
        page_object_number: PageObjectNumber,
        left: f64,
        bottom: f64,
        right: f64,
        top: f64,
    },
    /// The page's content bounding box rather than its crop box.
    #[serde(rename = "fitB")]
    FitB {
        #[serde(rename = "page", with = "crate::identity::page_ref")]
        page_object_number: PageObjectNumber,
    },
    #[serde(rename = "fitBH")]
    FitBh {
        #[serde(rename = "page", with = "crate::identity::page_ref")]
        page_object_number: PageObjectNumber,
        top: Option<f64>,
    },
    #[serde(rename = "fitBV")]
    FitBv {
        #[serde(rename = "page", with = "crate::identity::page_ref")]
        page_object_number: PageObjectNumber,
        left: Option<f64>,
    },
}

impl PdfDestination {
    pub fn page_object_number(&self) -> PageObjectNumber {
        match self {
            Self::Xyz { page_object_number, .. }
            | Self::Fit { page_object_number }
            | Self::FitH { page_object_number, .. }
            | Self::FitV { page_object_number, .. }
            | Self::FitR { page_object_number, .. }
            | Self::FitB { page_object_number }
            | Self::FitBh { page_object_number, .. }
            | Self::FitBv { page_object_number, .. } => *page_object_number,
        }
    }
}

/// `PDFDEST_VIEW_*` from `public/fpdf_doc.h`.
mod view {
    pub const XYZ: i32 = 1;
    pub const FIT: i32 = 2;
    pub const FIT_H: i32 = 3;
    pub const FIT_V: i32 = 4;
    pub const FIT_R: i32 = 5;
    pub const FIT_B: i32 = 6;
    pub const FIT_BH: i32 = 7;
    pub const FIT_BV: i32 = 8;
}

/// Materialize a destination.
///
/// `None` when it is unreadable: no visible indirect page, or a fit type this
/// build does not know. Coordinates stay raw; no conversion happens here.
pub fn read_destination(raw: &RawDestination<'_>) -> Option<PdfDestination> {
    let page_object_number = PageObjectNumber::new(raw.page_object_number()).ok()?;
    let view = raw.view();
    // A null parameter (the viewer keeps its value) reads as `None`, not the
    // 0 `FPDFDest_GetView` reports for it.
    let nulls = raw.view_null_params();
    let at = |i: usize| -> Option<f64> {
        (i < view.param_count && nulls & (1 << i) == 0).then(|| f64::from(view.params[i]))
    };

    Some(match view.code {
        view::XYZ => {
            let location = raw.location();
            PdfDestination::Xyz {
                page_object_number,
                left: location.left.map(f64::from),
                top: location.top.map(f64::from),
                zoom: location.zoom.map(f64::from),
            }
        }
        view::FIT => PdfDestination::Fit { page_object_number },
        view::FIT_H => PdfDestination::FitH { page_object_number, top: at(0) },
        view::FIT_V => PdfDestination::FitV { page_object_number, left: at(0) },
        view::FIT_R => {
            // `/FitR` is only meaningful with the whole rect. A malformed one
            // degrades to the whole page rather than inventing coordinates a
            // viewer would then scroll to.
            if view.param_count < 4 {
                PdfDestination::Fit { page_object_number }
            } else {
                PdfDestination::FitR {
                    page_object_number,
                    left: f64::from(view.params[0]),
                    bottom: f64::from(view.params[1]),
                    right: f64::from(view.params[2]),
                    top: f64::from(view.params[3]),
                }
            }
        }
        view::FIT_B => PdfDestination::FitB { page_object_number },
        view::FIT_BH => PdfDestination::FitBh { page_object_number, top: at(0) },
        view::FIT_BV => PdfDestination::FitBv { page_object_number, left: at(0) },
        _ => return None,
    })
}

//! Detached action models, and the destinations they point at.
//!
//! PDFium builds an action model out of a `/A` entry: a graph of nodes with a
//! root, `/Next` children, and per-node payloads. The model is detached, so
//! reading it does not hold the document's action dictionaries open, and it
//! is closed explicitly.
//!
//! Everything here is a thin accessor. Deciding what a node means, budgeting
//! the walk and degrading an unreadable payload are the engine's job, in
//! `epdf_engine::features::actions`.

use crate::{Document, PdfiumError};

/// A node's index within its model.
pub type ActionNodeId = u32;

/// An action model, closed on drop.
///
/// Borrows its document, because every payload accessor that resolves a
/// destination or a URI needs the document the action came from.
#[derive(Debug)]
pub struct ActionModel<'doc> {
    handle: pdfium_sys::EPDF_ACTION_MODEL,
    document: &'doc Document,
}

/// Which of a page's two action slots to read.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum PageActionEvent {
    Open = 0,
    Close = 1,
}

impl Document {
    /// The action model for one of a page's events, or `None` when the page
    /// has no action there.
    pub fn page_action_model(
        &self,
        page_object_number: u32,
        event: PageActionEvent,
    ) -> Option<ActionModel<'_>> {
        // SAFETY: the handle is live for the borrow this returns.
        let handle = unsafe {
            pdfium_sys::EPDFDoc_GetPageActionModel(self.handle, page_object_number, event as i32)
        };
        (!handle.is_null()).then_some(ActionModel { handle, document: self })
    }
}

/// Wrap a raw action-model handle, for the accessors that live elsewhere.
///
/// `pub(crate)` because the handle type is PDFium's and nothing outside this
/// crate should be holding one.
pub(crate) fn action_model_from_raw(
    handle: pdfium_sys::EPDF_ACTION_MODEL,
    document: &Document,
) -> Option<ActionModel<'_>> {
    (!handle.is_null()).then_some(ActionModel { handle, document })
}

/// Which of an annotation's eleven action slots to read.
///
/// `EPDF_ANNOT_ACTION_*`. `Activate` is `/A`; the other ten are the entries
/// of `/AA`. The numbering is the fork's, not a PDF one, so it is written out
/// rather than derived.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AnnotationActionEvent {
    Activate = 0,
    CursorEnter = 1,
    CursorExit = 2,
    MouseDown = 3,
    MouseUp = 4,
    Focus = 5,
    Blur = 6,
    PageOpen = 7,
    PageClose = 8,
    PageVisible = 9,
    PageInvisible = 10,
}

impl Document {
    /// The action model for one of an annotation's events.
    ///
    /// Takes the annotation rather than hanging off it, because the model
    /// borrows the DOCUMENT: every payload accessor that resolves a
    /// destination or a URI needs it, and the annotation's own borrow is of
    /// the page.
    pub fn annotation_action_model(
        &self,
        annotation: &crate::Annotation<'_>,
        event: AnnotationActionEvent,
    ) -> Option<ActionModel<'_>> {
        // SAFETY: both handles are live for the borrow this returns.
        let handle =
            unsafe { pdfium_sys::EPDFAnnot_GetActionModel(annotation.as_raw(), event as i32) };
        (!handle.is_null()).then_some(ActionModel { handle, document: self })
    }
}

impl Document {
    /// The destination a link annotation's direct `/Dest` names.
    ///
    /// `/Dest` is DATA, not an action, and it is consulted only when the
    /// annotation has no `/A` at all. A link carrying both is following its
    /// action; §12.5.6.5 gives `/A` precedence and a viewer that fell back to
    /// `/Dest` when the action was broken would navigate somewhere the
    /// document did not ask for.
    pub fn link_destination(
        &self,
        annotation: &crate::Annotation<'_>,
    ) -> Option<RawDestination<'_>> {
        // SAFETY: the annotation handle is live for the call.
        let link = unsafe { pdfium_sys::FPDFAnnot_GetLink(annotation.as_raw()) };
        if link.is_null() {
            return None;
        }
        // SAFETY: both handles are live for the borrow this returns.
        let dest = unsafe { pdfium_sys::FPDFLink_GetDest(self.handle, link) };
        (!dest.is_null()).then_some(RawDestination { dest, document: self })
    }
}

/// Which catalog-level event to read.
///
/// `EPDF_DOC_ACTION_*`. `/OpenAction` is not in this list because it is a
/// separate entry with a separate accessor, and because it may be a
/// destination rather than an action.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum DocumentActionEvent {
    WillClose = 0,
    WillSave = 1,
    DidSave = 2,
    WillPrint = 3,
    DidPrint = 4,
}

impl Document {
    /// The catalog's `/OpenAction`, in its action form.
    ///
    /// `None` also covers the destination form, which
    /// [`Document::open_action_destination`] reads.
    pub fn open_action_model(&self) -> Option<ActionModel<'_>> {
        // SAFETY: the handle is live for the borrow this returns.
        let handle = unsafe { pdfium_sys::EPDFDoc_GetOpenActionModel(self.handle) };
        (!handle.is_null()).then_some(ActionModel { handle, document: self })
    }

    /// The catalog's `/OpenAction` in its destination form
    /// (`EPDFDoc_GetOpenActionDest`), a named value resolved through the
    /// catalog. `None` when `/OpenAction` is absent, malformed or an action.
    pub fn open_action_destination(&self) -> Option<RawDestination<'_>> {
        // SAFETY: the handle is live; the destination points into the live
        // document and is valid for the borrow this returns.
        let dest = unsafe { pdfium_sys::EPDFDoc_GetOpenActionDest(self.handle) };
        (!dest.is_null()).then_some(RawDestination { dest, document: self })
    }

    /// One of the catalog's additional actions.
    pub fn document_action_model(&self, event: DocumentActionEvent) -> Option<ActionModel<'_>> {
        // SAFETY: as above.
        let handle =
            unsafe { pdfium_sys::EPDFDoc_GetAdditionalActionModel(self.handle, event as i32) };
        (!handle.is_null()).then_some(ActionModel { handle, document: self })
    }

    /// How many scripts the document's JavaScript name tree holds.
    pub fn name_tree_script_count(&self) -> i32 {
        unsafe { pdfium_sys::FPDFDoc_GetJavaScriptActionCount(self.handle) }
    }

    /// One name-tree script's key.
    ///
    /// The handle is opened and closed here, because the name is the only
    /// thing it is good for: the script itself comes through
    /// [`Document::name_tree_script_model`].
    pub fn name_tree_script_name(&self, index: i32) -> Result<Option<String>, PdfiumError> {
        // SAFETY: the handle is live; a null result is the documented failure.
        let handle = unsafe { pdfium_sys::FPDFDoc_GetJavaScriptAction(self.handle, index) };
        if handle.is_null() {
            return Ok(None);
        }
        let name = read_utf16(|buf, len| unsafe {
            pdfium_sys::FPDFJavaScriptAction_GetName(handle, buf, len)
        });
        // SAFETY: opened above and closed exactly once, whatever the read did.
        unsafe { pdfium_sys::FPDFDoc_CloseJavaScriptAction(handle) };
        name
    }

    /// One name-tree script's action model.
    pub fn name_tree_script_model(&self, index: i32) -> Option<ActionModel<'_>> {
        // SAFETY: as above.
        let handle =
            unsafe { pdfium_sys::EPDFDoc_GetNamedJavaScriptActionModel(self.handle, index) };
        (!handle.is_null()).then_some(ActionModel { handle, document: self })
    }
}

impl ActionModel<'_> {
    /// How many nodes the model holds. The bound on any walk of it.
    pub fn node_count(&self) -> i32 {
        unsafe { pdfium_sys::EPDFAction_GetNodeCount(self.handle) }
    }

    /// The native warning bits.
    pub fn warning_flags(&self) -> u32 {
        unsafe { pdfium_sys::EPDFAction_GetWarningFlags(self.handle) }
    }

    /// Whether PDFium walked the whole thing.
    pub fn is_complete(&self) -> bool {
        unsafe { pdfium_sys::EPDFAction_IsComplete(self.handle) != 0 }
    }

    /// The root node's id, as PDFium reports it. The caller validates.
    pub fn root_node_raw(&self) -> i64 {
        i64::from(unsafe { pdfium_sys::EPDFAction_GetRootNode(self.handle) })
    }

    pub fn node_type(&self, node: ActionNodeId) -> i32 {
        unsafe { pdfium_sys::EPDFAction_GetNodeType(self.handle, node) }
    }

    pub fn next_count(&self, node: ActionNodeId) -> i32 {
        unsafe { pdfium_sys::EPDFAction_GetNextCount(self.handle, node) }
    }

    /// The id of one `/Next` child, as reported. The caller validates.
    pub fn next_at_raw(&self, node: ActionNodeId, index: i32) -> i64 {
        i64::from(unsafe { pdfium_sys::EPDFAction_GetNextAt(self.handle, node, index) })
    }

    /// The raw `/S` name, kept for unknown and future action types.
    pub fn node_subtype(&self, node: ActionNodeId) -> Result<Option<String>, PdfiumError> {
        // SAFETY: measure-then-fill with a null probe, as every string
        // accessor here does.
        read_utf8(|buf, len| unsafe {
            pdfium_sys::EPDFAction_GetNodeSubtype(self.handle, node, buf.cast(), len)
        })
    }

    pub fn node_javascript(&self, node: ActionNodeId) -> Result<Option<String>, PdfiumError> {
        if unsafe { pdfium_sys::EPDFAction_NodeHasJavaScript(self.handle, node) } == 0 {
            return Ok(None);
        }
        read_utf16(|buf, len| unsafe {
            pdfium_sys::EPDFAction_GetNodeJavaScript(self.handle, node, buf, len)
        })
        .map(|s| Some(s.unwrap_or_default()))
    }

    /// Whether the node carries a script at all, which `rendition` needs to
    /// distinguish from a node whose script is empty.
    pub fn node_has_javascript(&self, node: ActionNodeId) -> bool {
        unsafe { pdfium_sys::EPDFAction_NodeHasJavaScript(self.handle, node) != 0 }
    }

    pub fn node_uri(&self, node: ActionNodeId) -> Result<Option<String>, PdfiumError> {
        read_utf8(|buf, len| unsafe {
            pdfium_sys::EPDFAction_GetNodeURI(self.document.handle, self.handle, node, buf, len)
        })
    }

    pub fn node_name(&self, node: ActionNodeId) -> Result<Option<String>, PdfiumError> {
        read_utf8(|buf, len| unsafe {
            pdfium_sys::EPDFAction_GetNodeName(self.handle, node, buf, len)
        })
    }

    pub fn node_file_path(&self, node: ActionNodeId) -> Result<Option<String>, PdfiumError> {
        read_utf8(|buf, len| unsafe {
            pdfium_sys::EPDFAction_GetNodeFilePath(self.handle, node, buf, len)
        })
    }

    /// The destination a `goto` node points at.
    pub fn node_destination(&self, node: ActionNodeId) -> Option<RawDestination<'_>> {
        // SAFETY: both handles are live for this borrow.
        let dest =
            unsafe { pdfium_sys::EPDFAction_GetNodeDest(self.document.handle, self.handle, node) };
        (!dest.is_null()).then_some(RawDestination { dest, document: self.document })
    }
}

impl Drop for ActionModel<'_> {
    fn drop(&mut self) {
        // SAFETY: loaded above and closed exactly once.
        unsafe { pdfium_sys::EPDFAction_CloseModel(self.handle) };
    }
}

/// A live `FPDF_DEST` and the document it belongs to.
///
/// Borrowed rather than owned: PDFium hands out a pointer into the document's
/// own structures, and there is nothing to close.
#[derive(Debug, Clone, Copy)]
pub struct RawDestination<'doc> {
    dest: pdfium_sys::FPDF_DEST,
    document: &'doc Document,
}

/// A destination's fit type and parameters, straight from PDFium.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct DestinationView {
    /// `PDFDEST_VIEW_*`.
    pub code: i32,
    pub params: [f32; 4],
    pub param_count: usize,
}

/// The three `/XYZ` components, each present or retaining the current value.
#[derive(Debug, Clone, Copy, PartialEq, Default)]
pub struct DestinationLocation {
    pub left: Option<f32>,
    pub top: Option<f32>,
    pub zoom: Option<f32>,
}

impl<'doc> RawDestination<'doc> {
    /// Wrap a destination handle a reader of another module answered;
    /// `None` for a null one.
    pub(crate) fn from_raw(dest: pdfium_sys::FPDF_DEST, document: &'doc Document) -> Option<Self> {
        (!dest.is_null()).then_some(Self { dest, document })
    }
}

impl RawDestination<'_> {
    /// The page this destination names, or zero when it names none.
    pub fn page_object_number(&self) -> u32 {
        unsafe { pdfium_sys::EPDFDest_GetPageObjectNumber(self.document.handle, self.dest) }
    }

    pub fn view(&self) -> DestinationView {
        // `count` is an unsigned long here, not an int: FPDFDest_GetView
        // reports how many parameters it wrote.
        let mut count: std::os::raw::c_ulong = 0;
        // Four is the most any fit type writes, which is `/FitR`.
        let mut params = [0f32; 4];
        // SAFETY: `params` is four floats and `count` is an initialized local.
        let code =
            unsafe { pdfium_sys::FPDFDest_GetView(self.dest, &mut count, params.as_mut_ptr()) };
        DestinationView { code: code as i32, params, param_count: (count as usize).min(4) }
    }

    /// Which view parameters are null, where the viewer keeps its current
    /// value (`EPDFDest_GetViewNullParams`): bit `i` is set when parameter
    /// `i` of [`RawDestination::view`] is null, which that reports as 0.
    pub fn view_null_params(&self) -> u32 {
        // SAFETY: the destination is live for the borrow of its document.
        unsafe { pdfium_sys::EPDFDest_GetViewNullParams(self.dest) }
    }

    pub fn location(&self) -> DestinationLocation {
        let (mut has_left, mut has_top, mut has_zoom) = (0i32, 0i32, 0i32);
        let (mut left, mut top, mut zoom) = (0f32, 0f32, 0f32);
        // SAFETY: six initialized locals, as the signature asks for.
        let ok = unsafe {
            pdfium_sys::FPDFDest_GetLocationInPage(
                self.dest,
                &mut has_left,
                &mut has_top,
                &mut has_zoom,
                &mut left,
                &mut top,
                &mut zoom,
            )
        };
        if ok == 0 {
            return DestinationLocation::default();
        }
        DestinationLocation {
            left: (has_left != 0).then_some(left),
            top: (has_top != 0).then_some(top),
            zoom: (has_zoom != 0).then_some(zoom),
        }
    }
}

/// Measure then fill, for a UTF-8 accessor.
///
/// The reported length counts the terminator, and a length of one or less is
/// an absent value rather than an empty one.
pub(crate) fn read_utf8<F>(mut call: F) -> Result<Option<String>, PdfiumError>
where
    F: FnMut(*mut std::ffi::c_void, std::os::raw::c_ulong) -> std::os::raw::c_ulong,
{
    let bytes = call(std::ptr::null_mut(), 0);
    if bytes <= 1 {
        return Ok(None);
    }
    let mut buffer: Vec<u8> = Vec::new();
    buffer.try_reserve_exact(bytes as usize).map_err(|_| PdfiumError::OutOfMemory)?;
    buffer.resize(bytes as usize, 0u8);

    let written = call(buffer.as_mut_ptr().cast(), bytes);
    if written == 0 {
        return Ok(None);
    }
    let produced = (written as usize).saturating_sub(1).min(buffer.len());
    Ok(Some(String::from_utf8_lossy(&buffer[..produced]).into_owned()))
}

/// Measure then fill, for a UTF-16 accessor. The length is in bytes.
pub(crate) fn read_utf16<F>(mut call: F) -> Result<Option<String>, PdfiumError>
where
    F: FnMut(*mut u16, std::os::raw::c_ulong) -> std::os::raw::c_ulong,
{
    let bytes = call(std::ptr::null_mut(), 0);
    if bytes <= 2 {
        return Ok(None);
    }
    let units = (bytes as usize).div_ceil(2);
    let mut buffer: Vec<u16> = Vec::new();
    buffer.try_reserve_exact(units).map_err(|_| PdfiumError::OutOfMemory)?;
    buffer.resize(units, 0u16);

    let written = call(buffer.as_mut_ptr(), bytes);
    if written == 0 {
        return Ok(None);
    }
    let produced = ((written as usize) / 2).saturating_sub(1).min(buffer.len());
    Ok(Some(String::from_utf16_lossy(&buffer[..produced])))
}

//! The rich text of a free text, and the wire between it and the fork.
//!
//! Ports `core/src/dto/RichText.ts` (the DTO) and
//! `services/src/features/annotations/internal/richTextWire.ts` (the wire).
//!
//! The fork's `EPDFAnnot_GetRichTextJSON` / `EPDFAnnot_SetRichTextJSON` JSON
//! is the DTO shape plus `source` and `diagnostics`, so reading is a parse and
//! writing is a stringify, except for FACES. The DTO names a face the way the
//! host does (a registered font's key, a standard font's kebab name); the fork
//! names it the way a PDF does (family, weight, italic). Both directions map
//! here.
//!
//! Only what the engine itself reasons about is typed: the body's face, size,
//! colour and alignment. Paragraph properties and run deltas are carried as
//! JSON objects, verbatim, because the engine only ever passes them through
//! and a typed copy would drop whatever the fork adds next.

use serde::{Deserialize, Serialize};
use serde_json::{Map, Value};

use crate::error::{EngineError, EngineErrorCode};
use crate::features::annotation::vocabulary::{StandardFont, TextAlignment};

/// `RichTextBody`: the complete body style and paragraph defaults.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct RichTextBody {
    pub family: String,
    /// 100..900.
    pub weight: u32,
    pub italic: bool,
    /// Points.
    pub size: f64,
    /// `#RRGGBB`.
    pub color: String,
    pub decoration: Vec<String>,
    pub script: String,
    pub letter_spacing: f64,
    pub horizontal_scale: f64,
    /// `left`, `center`, `right` or `justify`.
    pub align: String,
    /// `ltr` or `rtl`.
    pub dir: String,
    /// `lineHeight`, `margins`, `textIndent`, `unknown`: whatever else the
    /// fork reports, kept as it came.
    #[serde(flatten)]
    pub rest: Map<String, Value>,
}

/// `RichTextRun`. The style holds only what the run overrides.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct RichTextRun {
    /// May contain `\r`: a hard line break inside the paragraph.
    pub text: String,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub style: Option<Map<String, Value>>,
}

/// `RichTextParagraph`: its runs, and the paragraph properties it overrides.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct RichTextParagraph {
    pub runs: Vec<RichTextRun>,
    #[serde(flatten)]
    pub props: Map<String, Value>,
}

/// `RichTextDocument`: what an annotation reads back.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct RichTextDocument {
    pub body: RichTextBody,
    pub paragraphs: Vec<RichTextParagraph>,
}

/// `RichTextDocumentInput`: what a draft or patch writes. An absent body
/// keeps the annotation's current body style; a partial one takes the
/// fork's defaults for what it leaves out.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct RichTextDocumentInput {
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub body: Option<Map<String, Value>>,
    pub paragraphs: Vec<RichTextParagraph>,
}

impl RichTextBody {
    /// The body alignment as a `/Q` value. `None` for `justify`, which `/Q`
    /// cannot say, and for anything unrecognized.
    pub fn text_alignment(&self) -> Option<TextAlignment> {
        match self.align.as_str() {
            "left" => Some(TextAlignment::Left),
            "center" => Some(TextAlignment::Center),
            "right" => Some(TextAlignment::Right),
            _ => None,
        }
    }
}

/// `richTextPlainText`: paragraphs joined by `\r`, runs concatenated. What the
/// fork writes to `/Contents`.
pub fn plain_text(paragraphs: &[RichTextParagraph]) -> String {
    paragraphs
        .iter()
        .map(|p| p.runs.iter().map(|r| r.text.as_str()).collect::<String>())
        .collect::<Vec<_>>()
        .join("\r")
}

/// `richTextParagraphsFromPlainText`: one paragraph per line break, one run
/// each, no overrides.
pub fn paragraphs_from_plain_text(text: &str) -> Vec<RichTextParagraph> {
    let mut lines = Vec::new();
    let mut rest = text;
    loop {
        match rest.find(['\r', '\n']) {
            Some(at) => {
                lines.push(&rest[..at]);
                let skip = if rest[at..].starts_with("\r\n") { 2 } else { 1 };
                rest = &rest[at + skip..];
            }
            None => {
                lines.push(rest);
                break;
            }
        }
    }
    lines
        .into_iter()
        .map(|line| RichTextParagraph {
            runs: vec![RichTextRun { text: line.to_owned(), style: None }],
            props: Map::new(),
        })
        .collect()
}

/// A face as the fork names one. Weight and italic are absent when the name
/// alone does not imply them.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct FaceRequest {
    pub family: String,
    pub weight: Option<u32>,
    pub italic: Option<bool>,
}

/// What a registered font key resolves to.
pub type DescribeFont<'a> = &'a dyn Fn(&str) -> Option<pdfium::FontIdentity>;
/// The registered key whose identity matches a face.
pub type KeyForFace<'a> = &'a dyn Fn(&str, u32, bool) -> Option<String>;

/// `STANDARD_FACES`: the family, weight and italic of each standard name.
pub(crate) fn standard_face(font: StandardFont) -> (&'static str, u32, bool) {
    use StandardFont as S;
    match font {
        S::Courier => ("Courier", 400, false),
        S::CourierBold => ("Courier", 700, false),
        S::CourierBoldOblique => ("Courier", 700, true),
        S::CourierOblique => ("Courier", 400, true),
        S::Helvetica => ("Helvetica", 400, false),
        S::HelveticaBold => ("Helvetica", 700, false),
        S::HelveticaBoldOblique => ("Helvetica", 700, true),
        S::HelveticaOblique => ("Helvetica", 400, true),
        S::TimesRoman => ("Times", 400, false),
        S::TimesBold => ("Times", 700, false),
        S::TimesBoldItalic => ("Times", 700, true),
        S::TimesItalic => ("Times", 400, true),
        S::Symbol => ("Symbol", 400, false),
        S::ZapfDingbats => ("ZapfDingbats", 400, false),
    }
}

/// `familyKey`: families compare without case, spaces, hyphens, underscores
/// and quotes, which is the fork's own rule.
pub fn family_key(family: &str) -> String {
    family
        .chars()
        .filter(|c| !c.is_whitespace() && !matches!(c, '-' | '_' | '\'' | '"'))
        .flat_map(char::to_lowercase)
        .collect()
}

/// `STANDARD_FAMILY_KEYS`: the family names that mean a standard family.
pub(crate) fn standard_family(key: &str) -> Option<&'static str> {
    Some(match key {
        "helvetica" | "arial" | "arialmt" | "sansserif" => "Helvetica",
        "times" | "timesroman" | "timesnewroman" | "timesnewromanpsmt" | "serif" => "Times",
        "courier" | "couriernew" | "couriernewpsmt" | "monospace" => "Courier",
        "symbol" => "Symbol",
        "zapfdingbats" | "dingbats" => "ZapfDingbats",
        _ => return None,
    })
}

/// `faceForFreeTextFont`: the face a `fontFamily` (or a run's `family`) asks
/// for. A standard name's family, weight and italic; a registered key's
/// resolved identity; or, for anything else, the string itself as a family.
pub fn face_for_free_text_font(font: &str, describe: Option<DescribeFont<'_>>) -> FaceRequest {
    if let Some(standard) = StandardFont::from_family(font) {
        let (family, weight, italic) = standard_face(standard);
        return FaceRequest {
            family: family.to_owned(),
            weight: Some(weight),
            italic: Some(italic),
        };
    }
    if let Some(identity) = describe.and_then(|describe| describe(font)) {
        return FaceRequest {
            family: identity.family_name,
            weight: Some(u32::try_from(identity.weight).unwrap_or(400)),
            italic: Some(identity.italic),
        };
    }
    FaceRequest { family: font.to_owned(), weight: None, italic: None }
}

/// `freeTextFontForFace`: the DTO `fontFamily` for a body face. The
/// registered key whose identity matches, else the standard name, else the
/// family itself.
pub fn free_text_font_for_face(
    family: &str,
    weight: u32,
    italic: bool,
    key_for_face: Option<KeyForFace<'_>>,
) -> String {
    if let Some(key) = key_for_face.and_then(|lookup| lookup(family, weight, italic)) {
        return key;
    }
    if let Some(standard) = standard_family(&family_key(family)) {
        let bold = weight >= 600;
        let same_family =
            || StandardFont::ALL.into_iter().filter(move |f| standard_face(*f).0 == standard);
        if let Some(font) = same_family().find(|f| {
            let (_, w, i) = standard_face(*f);
            (w >= 600) == bold && i == italic
        }) {
            return font.as_str().to_owned();
        }
        // Symbol and ZapfDingbats have no bold or italic faces.
        if let Some(font) = same_family().next() {
            return font.as_str().to_owned();
        }
    }
    family.to_owned()
}

/// `withEngineFace`: a style's `family` rewritten to what the fork resolves
/// by, with the weight and italic a key or standard name implies. An explicit
/// `weight` or `italic` in the style still wins.
fn with_engine_face(
    style: &Map<String, Value>,
    describe: Option<DescribeFont<'_>>,
) -> Map<String, Value> {
    let Some(family) = style.get("family").and_then(Value::as_str) else {
        return style.clone();
    };
    let face = face_for_free_text_font(family, describe);
    let mut out = style.clone();
    out.insert("family".into(), Value::String(face.family));
    if let Some(weight) = face.weight
        && !style.contains_key("weight")
    {
        out.insert("weight".into(), Value::from(weight));
    }
    if let Some(italic) = face.italic
        && !style.contains_key("italic")
    {
        out.insert("italic".into(), Value::Bool(italic));
    }
    out
}

/// `engineRichTextJson`: the fork's JSON for a write, faces resolved.
pub fn engine_rich_text_json(
    input: &RichTextDocumentInput,
    describe: Option<DescribeFont<'_>>,
) -> String {
    let paragraphs: Vec<RichTextParagraph> = input
        .paragraphs
        .iter()
        .map(|p| RichTextParagraph {
            runs: p
                .runs
                .iter()
                .map(|r| RichTextRun {
                    text: r.text.clone(),
                    style: r.style.as_ref().map(|s| with_engine_face(s, describe)),
                })
                .collect(),
            props: p.props.clone(),
        })
        .collect();
    let document = RichTextDocumentInput {
        body: input.body.as_ref().map(|b| with_engine_face(b, describe)),
        paragraphs,
    };
    serde_json::to_string(&document).expect("a rich text document serializes")
}

/// `parseEngineRichText`: the fork's JSON in the DTO shape, its `source` and
/// `diagnostics` dropped. `None` when it is not what the fork writes.
pub fn parse_engine_rich_text(json: &str) -> Option<RichTextDocument> {
    let mut raw: Map<String, Value> = serde_json::from_str(json).ok()?;
    let mut body = match raw.remove("body") {
        Some(Value::Object(body)) => body,
        _ => return None,
    };
    let mut paragraphs = match raw.remove("paragraphs") {
        Some(paragraphs @ Value::Array(_)) => paragraphs,
        _ => return None,
    };
    body.remove("source");
    // Every colour as the engine gives colours: `#rrggbb`, lowercase
    // (`withLowercaseColor`), the body's and each run's.
    lowercase_color(&mut body);
    for paragraph in paragraphs.as_array_mut().into_iter().flatten() {
        let runs = paragraph.get_mut("runs").and_then(Value::as_array_mut);
        for run in runs.into_iter().flatten() {
            if let Some(Value::Object(style)) = run.get_mut("style") {
                lowercase_color(style);
            }
        }
    }
    Some(RichTextDocument {
        body: serde_json::from_value(Value::Object(body)).ok()?,
        paragraphs: serde_json::from_value(paragraphs).ok()?,
    })
}

/// `withLowercaseColor`.
fn lowercase_color(style: &mut Map<String, Value>) {
    if let Some(Value::String(color)) = style.get_mut("color") {
        *color = color.to_lowercase();
    }
}

/// `readEngineRichText`.
pub fn read_rich_text(annotation: &pdfium::Annotation<'_>) -> Option<RichTextDocument> {
    annotation.rich_text_json().ok().flatten().as_deref().and_then(parse_engine_rich_text)
}

/// `writeRichText`: `/RC`, `/DS`, `/DA`, `/Contents` and the appearance
/// through the fork's rich writer, all or nothing.
pub fn write_rich_text(
    annotation: &pdfium::Annotation<'_>,
    input: &RichTextDocumentInput,
    describe: Option<DescribeFont<'_>>,
) -> Result<(), EngineError> {
    let json = engine_rich_text_json(input, describe);
    let ok = annotation.set_rich_text_json(&json).map_err(|_| {
        EngineError::with_message(EngineErrorCode::InvalidArg, "rich text JSON contains NUL")
    })?;
    if !ok {
        return Err(EngineError::with_message(
            EngineErrorCode::InvalidArg,
            "rich text could not be written (empty rect, or a font resource could not be built)",
        ));
    }
    Ok(())
}

/// `assertRichTextAgreement`: a draft or patch carrying both `contents` and
/// `richText` must agree, `contents` being the plain projection. A stale DTO
/// echo fails loud here instead of quietly restoring old text.
pub fn assert_agreement(
    contents: Option<&str>,
    rich_text: Option<&RichTextDocumentInput>,
) -> Result<(), EngineError> {
    let (Some(contents), Some(rich_text)) = (contents, rich_text) else {
        return Ok(());
    };
    if contents != plain_text(&rich_text.paragraphs) {
        return Err(EngineError::with_message(
            EngineErrorCode::InvalidArg,
            "free-text: `contents` must equal the plain projection of `richText` when both are given",
        ));
    }
    Ok(())
}

/// `hexColor`: `#RRGGBB`, upper case, for a rich body colour.
pub fn hex_color(r: u8, g: u8, b: u8) -> String {
    format!("#{r:02X}{g:02X}{b:02X}")
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn a_standard_body_face_reads_back_as_its_kebab_name() {
        assert_eq!(free_text_font_for_face("Times", 700, false, None), "times-bold");
        assert_eq!(free_text_font_for_face("Helvetica", 400, true, None), "helvetica-oblique");
        assert_eq!(free_text_font_for_face("Arial MT", 400, false, None), "helvetica");
        assert_eq!(free_text_font_for_face("Symbol", 700, true, None), "symbol");
    }

    #[test]
    fn an_unresolvable_body_face_reads_back_as_itself_even_when_empty() {
        // a-bare-text-box in vectors/annotation/read.json: a /DA naming no
        // font the fork can resolve gives an empty body family.
        assert_eq!(free_text_font_for_face("", 400, false, None), "");
        assert_eq!(free_text_font_for_face("Noto Sans", 400, false, None), "Noto Sans");
    }

    #[test]
    fn a_registered_key_wins_over_the_standard_mapping() {
        let lookup = |family: &str, _: u32, _: bool| {
            (family_key(family) == "helvetica").then(|| "brand".to_owned())
        };
        assert_eq!(free_text_font_for_face("Helvetica", 400, false, Some(&lookup)), "brand");
    }

    #[test]
    fn a_standard_name_carries_its_face_into_the_engine_json() {
        let input = RichTextDocumentInput {
            body: Some(serde_json::from_str(r#"{"family":"courier-bold","italic":true}"#).unwrap()),
            paragraphs: paragraphs_from_plain_text("a\r\nb\nc"),
        };
        let json: Value = serde_json::from_str(&engine_rich_text_json(&input, None)).unwrap();
        assert_eq!(
            json["body"],
            serde_json::json!({"family":"Courier","weight":700,"italic":true})
        );
        assert_eq!(json["paragraphs"].as_array().unwrap().len(), 3);
        assert_eq!(json["paragraphs"][1], serde_json::json!({"runs":[{"text":"b"}]}));
    }

    #[test]
    fn the_engine_json_parses_without_its_source_and_diagnostics() {
        let json = r##"{"source":"contents","body":{"family":"","weight":400,"italic":false,
            "size":12,"color":"#000000","decoration":[],"script":"normal","letterSpacing":0,
            "horizontalScale":1,"align":"left","dir":"ltr"},"paragraphs":[{"runs":[]}],
            "diagnostics":[]}"##;
        let doc = parse_engine_rich_text(json).expect("parses");
        let back = serde_json::to_value(&doc).unwrap();
        assert!(back.get("source").is_none() && back.get("diagnostics").is_none());
        assert_eq!(back["paragraphs"], serde_json::json!([{"runs":[]}]));
        assert_eq!(doc.body.family, "");
        assert!(parse_engine_rich_text(r#"{"paragraphs":[]}"#).is_none());
    }

    #[test]
    fn contents_must_be_the_plain_projection() {
        let rich =
            RichTextDocumentInput { body: None, paragraphs: paragraphs_from_plain_text("a\nb") };
        assert!(assert_agreement(Some("a\rb"), Some(&rich)).is_ok());
        assert!(assert_agreement(Some("a\nb"), Some(&rich)).is_err());
        assert!(assert_agreement(None, Some(&rich)).is_ok());
    }

    #[test]
    fn body_colours_are_upper_case_hex() {
        assert_eq!(hex_color(200, 0, 10), "#C8000A");
    }
}

